CREATE OR REPLACE FUNCTION compute_rrs(recscore_val numeric, confval_val numeric, recutil_val numeric)
RETURNS numeric AS $$
BEGIN
    RETURN (recscore_val + confval_val + recutil_val) / 3;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION compute_rrs(recscore_val numeric, confval_val numeric, recutil_val numeric)
RETURNS numeric AS $$
BEGIN
    RETURN ROUND((recscore_val + confval_val + recutil_val) / 3, 2);
END;
$$ LANGUAGE plpgsql;
